"use strict";

const PATTERNS = [
  /ignore (all |any )?(previous|prior) instructions/i,
  /disregard (your|the) (rules|instructions)/i,
  /<\/?system>/i,
  /developer mode/i,
  /note to ai agents/i,
];

function clean(text, options = {}) {
  const out = String(text).slice(0, options.maxLength ?? 10000);
  return { text: out, flagged: PATTERNS.some((p) => p.test(out)) };
}

function strip(text) {
  process.emitWarning("inputsentry.strip() is deprecated; use inputsentry.clean() instead", "DeprecationWarning");
  return clean(text).text;
}

module.exports = { clean, strip };
